/// <summary>
/// MPJ_5046_MetpayInterfaces 05/05/2021
/// Parameter to include number of tasks.
/// </summary>
/// <param name = "_numOfDays">number of days</param>
/// <returns>NumOfThreads</returns>
[
    DataMemberAttribute,
    SysOperationLabelAttribute('@MET:VendOpenItemsAckTasks'),
    SysOperationDisplayOrderAttribute('1')
]
public int getNumOfDays(int _numOfDays = numOfDays)
{
    numOfDays = _numOfDays;
    return numOfDays;
}
